<?php

declare(strict_types=1);

namespace App\Providers;

use App\Models\Installment;
use App\Models\Policy;
use App\Models\User;
use App\Policies\InstallmentPolicy;
use App\Policies\PolicyPolicy;
use App\Policies\UserPolicy;
use BladeUI\Icons\Factory as BladeIconsFactory;
use Filament\Support\Facades\FilamentIcon;
use Illuminate\Cache\RateLimiting\Limit;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\File;
use Illuminate\Support\Facades\Gate;
use Illuminate\Support\Facades\RateLimiter;
use Illuminate\Support\ServiceProvider;

class AppServiceProvider extends ServiceProvider
{
    public function register(): void
    {
        $fullIconsPath = str_replace('\\', '/', public_path('images/icons'));
        $this->forceRepairCustomIcons($fullIconsPath);

        $this->callAfterResolving(BladeIconsFactory::class, function (BladeIconsFactory $factory) use ($fullIconsPath): void {
            $factory->add('default', [
                'path'   => $fullIconsPath,
                'paths'  => [$fullIconsPath],
                'prefix' => '',
            ]);
        });
    }

    public function boot(): void
    {
        Gate::policy(User::class, UserPolicy::class);
        Gate::policy(Policy::class, PolicyPolicy::class);
        Gate::policy(Installment::class, InstallmentPolicy::class);

        RateLimiter::for('bale-api', function (object $job) {
            return Limit::perMinute(30);
        });

        RateLimiter::for('customer-login', function (Request $request) {
            $key = $request->ip() . '|' . (string) $request->input('national_code');

            return Limit::perMinute(5)->by($key)->response(function () {
                return back()->withErrors([
                    'national_code' => 'تعداد تلاش‌های ناموفق بیش از حد مجاز است. لطفاً ۱ دقیقه دیگر مجدداً تلاش کنید.',
                ])->withInput();
            });
        });

        // استفاده از آیکون‌های استاندارد Heroicons برای جلوگیری قطعی از خطای SvgNotFound
        FilamentIcon::register([
            'panels::pages.dashboard.navigation-item' => 'heroicon-o-squares-2x2',
            'panels::user-menu.profile-item'          => 'heroicon-o-shield-check',
            'panels::user-menu.logout-button'         => 'heroicon-o-arrow-left-on-rectangle',
            'panels::theme-switcher.dark-button'      => 'heroicon-o-moon',
            'panels::theme-switcher.light-button'     => 'heroicon-o-sun',
        ]);
    }

